import { AxisScale } from '@visx/axis';
import { getTicks } from '@visx/scale';
import React from 'react';

import { DivAxisWrapper } from './DivAxisWrapper.js';
import { formatDateTicks } from '../../../functions/format-date-ticks.js';
import { getTickValues } from '../../../functions/format-value.js';
import { getHorizontalTimeAxisNumTicks } from '../../../functions/ticks.js';
import { Formatter } from '../../../types/formatter.js';
import { TickValueFormatter } from '../../../types/tick-value.js';
import { AxisBottom } from '../AxisBottom.js';
import { axisFontProps } from '../constants.js';
import { bottomTickLabelDateProps } from '../functions/get-tick-label-props.js';

/**
 * @internal
 */
export interface OldTimeBottomAxisProps {
  scale: AxisScale;
  containerWidth: number;
  containerHeight: number;
  formatter?: Formatter;
  label?: string;
  stroke?: string;
}

const TICK_LABEL_PROPS = bottomTickLabelDateProps;

/* TODO ADES-7102 Sparkline should use TimeBottomAxis and delete this file when refactored  */
/**
 * @internal
 */
export const OldTimeBottomAxis = (props: OldTimeBottomAxisProps) => {
  const { scale, containerWidth, containerHeight, label, stroke } = props;

  const numTicks = getHorizontalTimeAxisNumTicks(containerWidth);
  const ticks = getTicks(scale, numTicks);
  const tickValues = getTickValues(
    ticks,
    formatDateTicks as TickValueFormatter,
  );
  const tickFormat = (_: unknown, index: number) => tickValues[index];

  return (
    <DivAxisWrapper
      divAxisStyle={axisFontProps}
      ticks={tickValues}
      label={label}
      isTickVertical
    >
      <AxisBottom
        data-testid="time-axis-bottom"
        scale={scale}
        containerSize={containerWidth}
        height={containerHeight}
        numTicks={numTicks}
        tickValues={ticks}
        tickLabelProps={TICK_LABEL_PROPS}
        tickFormat={tickFormat}
        label={label}
        stroke={stroke}
      />
    </DivAxisWrapper>
  );
};

OldTimeBottomAxis['displayName'] = 'OldTimeBottomAxis';
